def eval_expression(expr: str) -> float:
    import re

    # Tokenize the expression into numbers, operators, and parentheses
    # This regex handles integers, decimals, negative numbers, operators, and parens.
    # It identifies unary/negative minus signs vs binary minus signs.

    def tokenize(expression):
        # Remove all whitespace
        expression = expression.replace(" ", "")
        tokens = []
        i = 0
        n = len(expression)

        while i < n:
            char = expression[i]

            # If it's a digit or decimal point, parse the full number
            if char.isdigit() or char == '.':
                num_str = char
                i += 1
                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    num_str += expression[i]
                    i += 1
                tokens.append(float(num_str) if '.' in num_str else int(num_str))

            # Handle operators and parentheses
            elif char in "+-*/()":
                # Check for unary minus (negative numbers)
                if char == '-' and (i == 0 or expression[i-1] in "(+-*/"):
                    # Look ahead to parse the negative number
                    i += 1
                    num_str = "-"
                    while i < n and (expression[i].isdigit() or expression[i] == '.'):
                        num_str += expression[i]
                        i += 1
                    tokens.append(float(num_str) if '.' in num_str else int(num_str))
                else:
                    tokens.append(char)
                    i += 1
            else:
                raise ValueError(f"Invalid character in expression: {char}")

        return tokens

    tokens = tokenize(expr)

    # Shunting-yard algorithm to convert infix to postfix (RPN)
    def to_rpn(tokens):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operator_stack = []

        for token in tokens:
            if isinstance(token, (int, float)):
                output.append(token)
            elif token in precedence:
                while (operator_stack and operator_stack[-1] in precedence and
                       precedence[operator_stack[-1]] >= precedence[token]):
                    output.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output.append(operator_stack.pop())
                if not operator_stack:
                    raise ValueError("Mismatched parentheses")
                operator_stack.pop() # Remove '('

        while operator_stack:
            op = operator_stack.pop()
            if op in '()':
                raise ValueError("Mismatched parentheses")
            output.append(op)

        return output

    rpn = to_rpn(tokens)

    # Evaluate RPN expression
    stack = []
    for token in rpn:
        if isinstance(token, (int, float)):
            stack.append(token)
        else:
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(a / b)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    result = stack[0]
    # Return as int if it's a whole number, else float
    return int(result) if result == int(result) else result
